            C#

    using System;
using System.Collections.Generic;

public class GFG {
    static bool validateOp(int[] a, int[] b) {
        Queue<int> q1 = new Queue<int>(a);
        Queue<int> q2 = new Queue<int>(b);
        Stack<int> st = new Stack<int>();

        // Dequeue all items one by one
        while (q1.Count > 0) {
            int ele = q1.Dequeue();

            if (ele == q2.Peek()) {

                // If matches, dequeue from output queue
                q2.Dequeue();

                // Pop from stack while top matches q2 front
                while (st.Count > 0 && q2.Count > 0 && st.Peek() == q2.Peek())
                {
                    st.Pop();
                    q2.Dequeue();
                }
            }
            else
            {
                st.Push(ele);
            }
        }

        return q2.Count == 0;
    }

    public static void Main() {
        int[] a = { 1, 2, 3 };
        int[] b = { 3, 2, 1 };

        if (validateOp(a, b))
            Console.WriteLine("true");
        else
            Console.WriteLine("false");
    }
}


